import {filterPeople,escapeHTML as e,safeURL,normalizeNotebook} from './model.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const storageKey='cosign-fieldnotes.notebook.v1';
let notebook, storageAvailable=true;
try {notebook=normalizeNotebook(JSON.parse(localStorage.getItem(storageKey)||'null'));} catch {notebook=normalizeNotebook(null);storageAvailable=false;}
let data={people:[],paths:[]}, filter='all', query='', savedOnly=false, activeView='library', lastFocus=null, activePerson=null, toastTimeout;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(notebook));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Export your notebook to keep it.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').hidden=true,3600);}
function sourceLinks(urls=[]){return [...new Set(urls.filter(Boolean))].map((url,i)=>`<a href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">${urls.length===1?'Read the evidence':`Source ${i+1}`} →</a>`).join('');}
function personCard(p,index){const saved=notebook.saved.includes(p.id);return `<article class="person-card"><button class="save-card" data-save="${e(p.id)}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} ${e(p.name)}">${saved?'♥':'♡'}</button><button class="card-main" data-open="${e(p.id)}" aria-label="Study ${e(p.name)}"><div class="card-top"><span class="discipline ${e(p.discipline)}">${e(p.discipline)}</span><span class="card-number">${String(index+1).padStart(2,'0')}</span></div><h3 class="card-name">${e(p.name)}</h3><p class="card-subtitle">${e(p.subtitle)}</p><div class="card-rule"></div><p class="card-focus">${e(p.focus)}</p></button><div class="card-footer"><span>${p.artifacts.length} sources · ${p.decisions.length} decisions${notebook.completed.includes(p.id)?' · Practiced ✓':''}</span><span aria-hidden="true">→</span></div></article>`;}
function bindCards(root){root.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openStudy(b.dataset.open)));root.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>toggleSave(b.dataset.save)));}
function toggleSave(id){const wasSaved=notebook.saved.includes(id);notebook.saved=wasSaved?notebook.saved.filter(x=>x!==id):[...notebook.saved,id];persist();renderLibrary();if(activeView==='notebook')renderNotebook();if(activePerson?.id===id)updateDialogSave();toast(wasSaved?'Removed from your reading queue.':'Saved to your reading queue.');}
function updateDialogSave(){const b=$('#dialog-save');if(b){const saved=notebook.saved.includes(activePerson.id);b.textContent=saved?'♥ Saved':'♡ Save study';b.setAttribute('aria-pressed',String(saved));}}
function renderLibrary(){const people=filterPeople(data.people,{discipline:filter,query,savedOnly,saved:notebook.saved});$('#people-grid').innerHTML=people.map(p=>personCard(p,data.people.indexOf(p))).join('');$('#result-count').textContent=`${people.length} ${people.length===1?'study':'studies'}${query?` matching “${query}”`:''}`;$('#empty-state').hidden=people.length!==0;bindCards($('#people-grid'));}
function renderCoverage(){const counts=['design','product','growth'].map(d=>`${data.people.filter(p=>p.discipline===d).length} ${d}`);$('#coverage-summary').textContent=`This edition contains ${counts.join(', ')} studies. The original lists are larger. Source coverage varies and is documented in each study. Last researched: ${data.updatedAt}.`;$('#discovery-queue').innerHTML=data.discovery?.length?`<div class="discovery-section"><p class="eyebrow">RESEARCH LEADS / NOT YET STUDIED</p>${data.discovery.map(p=>`<div class="discovery-row"><h3>${e(p.name)}</h3><div><p>${e(p.coverage)}</p><div class="evidence-links">${p.sources.map(a=>`<a href="${e(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${e(a.title)} →</a>`).join('')}</div></div></div>`).join('')}</div>`:'';}
function renderMetrics(){const sources=new Set(data.people.flatMap(p=>p.artifacts.map(a=>a.url)));$('#metrics').innerHTML=`<div class="metric"><strong>${data.people.length.toString().padStart(2,'0')}</strong><span>practitioner studies</span></div><div class="metric"><strong>${sources.size.toString().padStart(2,'0')}</strong><span>linked source works</span></div><div class="metric"><strong>03</strong><span>disciplines, one practice</span></div>`;}
function renderPaths(){const paths=data.paths?.length?data.paths:[{id:'craft',title:'Make the choice visible.',question:'How do you turn a point of view into a product people can feel?',disciplines:['design','product'],output:'Compare two implementations of one interaction. Name what each makes easier and what each sacrifices.'},{id:'judgment',title:'Choose what matters.',question:'How do you decide what to build, what to leave out, and what evidence is enough?',disciplines:['product','design'],output:'Write a one-page decision memo with an alternative, a tradeoff, and a condition that would change your mind.'},{id:'growth',title:'Earn the next user.',question:'How do you connect a useful product to a repeatable way of reaching people?',disciplines:['growth','product'],output:'Sketch one growth loop, its bottleneck, and a small experiment that could falsify your assumption.'}];$('#paths-content').innerHTML=paths.map((path,i)=>{const people=path.people?path.people.map(id=>data.people.find(p=>p.id===id)).filter(Boolean):data.people.filter(p=>path.disciplines.includes(p.discipline)).slice(i*2,i*2+4);return `<article class="path-card"><span class="path-index">0${i+1}</span><div><h2>${e(path.title)}</h2><p>${e(path.question)}</p><p class="path-output"><strong>Make something:</strong> ${e(path.output)}</p></div><div class="path-studies">${people.map((p,j)=>`<button class="path-study" data-open="${e(p.id)}"><span>0${j+1}</span><b>${e(p.name)}</b><span>${e(p.discipline)}</span> →</button>`).join('')}<p style="font-size:10px;margin-top:7px">Read the source. Make a prediction. Compare the tradeoff.</p></div></article>`;}).join('');if(data.comparisons?.length){$('#paths-content').insertAdjacentHTML('beforeend',`<section class="comparison-section"><p class="eyebrow">COMPARE, DO NOT COLLECT RULES</p><h2>Where the ideas meet.</h2><p class="page-intro">Original synthesis across the sources. Use the tension between two ideas to find the conditions under which each is useful.</p>${data.comparisons.map((c,i)=>`<details class="comparison"><summary><span>${String(i+1).padStart(2,'0')}</span>${e(c.title)}<b>+</b></summary><p>${e(c.analysis)}</p><div class="evidence-links">${sourceLinks(c.sourceUrls)}</div></details>`).join('')}</section>`);}bindCards($('#paths-content'));}
function renderNotebook(){const entries=data.people.filter(p=>notebook.saved.includes(p.id)||notebook.notes[p.id]?.trim()||notebook.predictions[p.id]?.trim()||notebook.completed.includes(p.id));$('#notebook-stats').textContent=`${notebook.saved.length} saved · ${notebook.completed.length} practiced · ${Object.values(notebook.notes).filter(x=>x.trim()).length} written reflections`;$('#notebook-content').innerHTML=entries.length?entries.map(p=>`<article class="notebook-record"><div><span class="discipline ${e(p.discipline)}">${e(p.discipline)}</span><h3>${e(p.name)}</h3><p>${e(p.focus)}</p><button data-open="${e(p.id)}">Open study & notes →</button>${notebook.completed.includes(p.id)?'<div class="completion">✓ Exercise completed</div>':''}</div><div>${notebook.predictions[p.id]?`<p><b>Before reading</b><br>${e(notebook.predictions[p.id])}</p><br>`:''}<p>${e(notebook.notes[p.id]||'No reflection yet. Open the study to capture what you notice.')}</p></div></article>`).join(''):`<div class="empty-state"><span>✳</span><h3>Make room for an idea.</h3><p>Save a study with the heart button or write a reflection in any exercise.</p><a class="button" href="#library">Explore the library →</a></div>`;bindCards($('#notebook-content'));}
function openStudy(id,fromHash=false){const p=data.people.find(x=>x.id===id);if(!p)return;lastFocus=document.activeElement;activePerson=p;const dialog=$('#study-dialog');$('#study-content').innerHTML=`<div class="dialog-head"><span>FIELD STUDY / ${e(p.discipline.toUpperCase())}</span><div class="dialog-actions"><button id="dialog-save"></button><button id="share-study" aria-label="Copy link to this study">Copy link</button><button class="close-dialog" id="close-study" aria-label="Close study">×</button></div></div><div class="study-inner"><span class="discipline ${e(p.discipline)}">${e(p.discipline)}</span><h1 id="study-title">${e(p.name)}</h1><p class="study-subtitle">${e(p.subtitle)}</p><p class="study-summary">${e(p.summary||p.focus)}</p><div class="coverage"><b>Research coverage</b><br>${e(p.coverage||'A bounded study of the linked public sources, not a complete career survey.')}</div><section class="study-section"><div class="section-heading"><span>01</span><h2>Start with the sources.</h2></div>${p.artifacts.map(a=>`<article class="source-item"><div class="source-top"><a href="${e(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${e(a.title)} →</a>${a.date?`<span>${e(a.date)}</span>`:''}</div><div class="source-meta">${e([a.author,a.kind,a.coverage].filter(Boolean).join(' · '))}</div><p>${e(a.summary)}</p>${a.attribution?`<p class="source-attribution">Attribution: ${e(a.attribution)}</p>`:''}</article>`).join('')}</section><section class="study-section"><div class="section-heading"><span>02</span><h2>Study the decisions.</h2></div><div class="prediction-box"><label class="notes-label" for="prediction">Before you reveal the decisions<small>From the source material, what would you prioritize? What would you give up? Write your prediction, then compare.</small></label><textarea id="prediction" placeholder="I would choose… because… The cost would be…">${e(notebook.predictions[p.id]||'')}</textarea><span class="save-status" id="prediction-status">Stored only in this browser.</span></div>${p.decisions.map((d,i)=>`<details class="decision"><summary>Decision ${String(i+1).padStart(2,'0')} <span>Reveal the choice +</span></summary><div class="decision-body"><h3>${e(d.title)}</h3><p>${e(d.detail)}</p>${d.alternative?`<p><b>The alternative:</b> ${e(d.alternative)}</p>`:''}${d.tradeoff?`<p><b>The tradeoff:</b> ${e(d.tradeoff)}</p>`:''}${d.limits?`<p><b>Keep in mind:</b> ${e(d.limits)}</p>`:''}${d.application?`<p><b>Try transferring it:</b> ${e(d.application)}</p>`:''}<div class="evidence-links">${sourceLinks(d.evidenceUrls)}</div></div></details>`).join('')}</section><section class="study-section"><div class="section-heading"><span>03</span><h2>Notice the explanation.</h2></div><p class="editorial-label">Editorial observations about communication, grounded in the linked examples.</p>${p.techniques.map(t=>`<article class="technique"><b>${e(t.title)}</b><p>${e(t.detail)}</p>${t.sourceUrl?`<div class="evidence-links">${sourceLinks([t.sourceUrl])}</div>`:''}</article>`).join('')}</section><section class="practice-box"><p class="eyebrow">04 / PUT IT TO WORK</p><h3>${e(p.exercise.title||'A small exercise in judgment.')}</h3><p>${e(p.exercise.task)}</p>${p.exercise.deliverable?`<p><b>Make:</b> ${e(p.exercise.deliverable)}</p>`:''}${p.exercise.evaluation?`<p><b>Evaluate:</b> ${e(p.exercise.evaluation)}</p>`:''}${p.exercises?.length>1?`<div class="more-exercises"><p class="eyebrow">OTHER WAYS TO PRACTICE</p>${p.exercises.slice(1).map(x=>`<details><summary>${e(x.title)}</summary><p>${e(x.task)}</p><p><b>Make:</b> ${e(x.deliverable)}</p><p><b>Evaluate:</b> ${e(x.evaluation)}</p></details>`).join('')}</div>`:''}<label class="notes-label" for="study-notes">Your reflection<small>What did you make? What changed your mind? These notes stay in this browser.</small><textarea id="study-notes" placeholder="One thing I noticed…\nOne choice I made…\nOne thing I’d test next…">${e(notebook.notes[p.id]||'')}</textarea></label><div class="practice-actions"><label><input id="exercise-complete" type="checkbox" ${notebook.completed.includes(p.id)?'checked':''}> I tried the exercise</label><span class="save-status" id="note-status">${storageAvailable?'Saves as you type.':'Storage unavailable. Export to keep notes.'}</span></div></section><section class="study-section"><div class="section-heading"><span>05</span><h2>Keep the limits in view.</h2></div><ul class="limits">${p.limitations.map(l=>`<li>${e(l)}</li>`).join('')}</ul></section></div>`;updateDialogSave();$('#dialog-save').addEventListener('click',()=>toggleSave(id));$('#close-study').addEventListener('click',()=>dialog.close());$('#share-study').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);toast('Study link copied.');}catch{toast('Copy the current URL to share this study.');}});$('#study-notes').addEventListener('input',ev=>{notebook.notes[id]=ev.target.value;$('#note-status').textContent=persist()?'Saved in this browser.':'Export notebook to keep your notes.';});$('#prediction').addEventListener('input',ev=>{notebook.predictions[id]=ev.target.value;$('#prediction-status').textContent=persist()?'Saved in this browser.':'Export notebook to keep your prediction.';});$('#exercise-complete').addEventListener('change',ev=>{notebook.completed=ev.target.checked?[...new Set([...notebook.completed,id])]:notebook.completed.filter(x=>x!==id);persist();renderLibrary();});if(!dialog.open)dialog.showModal();dialog.scrollTop=0;$('#close-study').focus();if(!fromHash)history.pushState(null,'',`#study/${id}`);}
function route(){const hash=decodeURIComponent(location.hash.slice(1)||'library');if(hash.startsWith('study/')){openStudy(hash.slice(6),true);return;}const view=['library','paths','notebook','about'].includes(hash)?hash:'library';activeView=view;$$('.view').forEach(v=>v.hidden=v.id!==`${view}-view`);$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if($('#study-dialog').open)$('#study-dialog').close();if(view==='notebook')renderNotebook();if(view==='paths')renderPaths();if(hash!=='collection')window.scrollTo({top:0,behavior:'instant'});}
$('#study-dialog').addEventListener('close',()=>{activePerson=null;if(location.hash.startsWith('#study/'))history.replaceState(null,'',`#${activeView}`);if(activeView==='notebook')renderNotebook();lastFocus?.focus?.();});$('#study-dialog').addEventListener('click',ev=>{if(ev.target===$('#study-dialog')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close();}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderLibrary();}));$('#search-input').addEventListener('input',ev=>{query=ev.target.value;renderLibrary();});$('#queue-toggle').addEventListener('click',()=>{savedOnly=!savedOnly;$('#queue-toggle').setAttribute('aria-pressed',String(savedOnly));$('#queue-toggle').textContent=savedOnly?'♥ Saved only':'♡ Saved only';renderLibrary();});$('#reset-search').addEventListener('click',()=>{query='';filter='all';savedOnly=false;$('#search-input').value='';$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='all')));$('#queue-toggle').setAttribute('aria-pressed','false');$('#queue-toggle').textContent='♡ Saved only';renderLibrary();});$('#export-notebook').addEventListener('click',()=>{const exportData={project:'Cosign Fieldnotes',exportedAt:new Date().toISOString(),...notebook,studies:data.people.filter(p=>notebook.saved.includes(p.id)||notebook.notes[p.id]||notebook.predictions[p.id]||notebook.completed.includes(p.id)).map(p=>({id:p.id,name:p.name,sources:p.artifacts.map(a=>a.url)}))};const blob=new Blob([JSON.stringify(exportData,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`cosign-fieldnotes-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);toast('Notebook exported. Keep the file somewhere safe.');});window.addEventListener('hashchange',route);document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#study-dialog').open){ev.preventDefault();if(activeView!=='library'){location.hash='library';}$('#search-input').focus();}});
try{const response=await fetch('./data/collection.json');if(!response.ok)throw new Error(`Data response ${response.status}`);data=await response.json();if(!Array.isArray(data.people))throw new Error('Invalid collection');if(data.repositoryUrl){$('#repo-link').href=safeURL(data.repositoryUrl);$('#repo-link').hidden=false;}renderMetrics();renderCoverage();renderLibrary();route();}catch(error){$('#people-grid').innerHTML='<div class="empty-state"><h3>The collection could not load.</h3><p>Please refresh the page. Your notebook is still stored in this browser.</p><button class="button" onclick="location.reload()">Try again</button></div>';$('#result-count').textContent='Unable to load studies';console.error(error);}
